           [("计算 sin30° + cos60° + tan45°。", "1/2 + 1/2 + 1 = 2。"), ("Rt△ABC 中 ∠C = 90°，AC = 6，BC = 8，求 sinA 和 tanA。", "AB = √(6² + 8²) = 10；sinA = BC/AB = 8/10 = 4/5；tanA = BC/AC = 8/6 = 4/3。")],
